const u8* fsbSetupHeader(u32 crc32, usize& lenOut) {
    // linear scan: 161 entries, called once per cached sound
    for (const E& e : kTable)
        if (e.crc == crc32) { lenOut = e.len; return e.p; }
    lenOut = 0;
    return nullptr;
}

